#!/usr/bin/env python3
"""Generate professional AXP historical stock report HTML."""
import json
import pandas as pd
import numpy as np

# Load analysis data
with open("/app/output/analysis_data.json") as f:
    data = json.load(f)

# Fix max drawdown peak date by recomputing correctly
df = pd.read_csv("/app/benchmark/data.csv")
df["Date"] = pd.to_datetime(df["Date"].str.replace(r"(\+|\-)\d{2}:\d{2}$", "", regex=True))
df = df.sort_values("Date").reset_index(drop=True)
cummax = df["Close"].cummax()
drawdown = (df["Close"] - cummax) / cummax
max_dd_idx = drawdown.idxmin()
peak_close_at_trough = cummax.iloc[max_dd_idx]
# Find the first time cummax reached the peak value (the actual peak date)
peak_idx = df[df["Close"] == peak_close_at_trough].index[0]
correct_peak_date = str(df.loc[peak_idx, "Date"].date())
correct_trough_date = str(df.loc[max_dd_idx, "Date"].date())

# Update KPI data
data["kpis"]["max_drawdown_peak_date"] = correct_peak_date
data["kpis"]["max_drawdown_trough_date"] = correct_trough_date

k = data["kpis"]
m = data["meta"]

# Recompute max drawdown correctly for top 5
# Find proper drawdown episodes
dd_series = drawdown
# Find major drawdown episodes (drop below -10%)
major_dds = []
in_dd = False
dd_start = None
dd_min_val = 0
dd_min_idx = 0
for i in range(len(df)):
    val = dd_series.iloc[i]
    if val < -0.10 and not in_dd:
        in_dd = True
        dd_start = i
        dd_min_val = val
        dd_min_idx = i
    elif in_dd:
        if val < dd_min_val:
            dd_min_val = val
            dd_min_idx = i
        if val > -0.02:
            in_dd = False
            # Find actual peak (max Close before drawdown start)
            pre_slice = df["Close"].iloc[:dd_start+1]
            peak_val = pre_slice.max()
            # Find first occurrence of this peak value
            peak_i_candidates = df[df["Close"] == peak_val].index
            peak_i = peak_i_candidates[peak_i_candidates <= dd_start][0] if len(peak_i_candidates[peak_i_candidates <= dd_start]) > 0 else dd_start
            major_dds.append({
                "peak_date": str(df.loc[peak_i, "Date"].date()),
                "trough_date": str(df.loc[dd_min_idx, "Date"].date()),
                "drawdown_pct": round(float(dd_min_val * 100), 2),
                "peak_price": round(float(peak_val), 2),
                "trough_price": round(float(df.loc[dd_min_idx, "Close"]), 2),
                "days_peak_to_trough": int((df.loc[dd_min_idx, "Date"] - df.loc[peak_i, "Date"]).days),
            })
major_dds.sort(key=lambda x: x["drawdown_pct"])
major_dds = major_dds[:5]
data["major_drawdowns"] = major_dds

